from lib import *
S = SS('j266')
steps = [
    step("在这台 macOS 上 Preferences.userRoot() 的实现类是 java.util.prefs.MacOSXPreferences,数据存在 ~/Library/Preferences/com.apple.java.util.prefs.plist(defaults read com.apple.java.util.prefs 里能看到刚写入的 j266test_zen 节点)。节点路径用 /,例如 /j266test_zen,name() 是最后一段,parent() 是 /。写 systemRoot 会失败:BackingStoreException: Synchronization failed for node '/j266test_zen_sys/'(没有权限)。这个实验用的节点最后都用 removeNode 清除了,defaults read 里不再含有。", t=tl(S(1)), done=lidx(S(1), 'userRoot 实现类', '节点 /j266test_zen', 'put 之后 get'), mark=lidx(S(1), 'systemRoot 写入', '存储文件', 'defaults read'), kv=KV([['userRoot', 'MacOSXPreferences → com.apple.java.util.prefs.plist'], ['systemRoot 写入', 'BackingStoreException(无权限)']], ['userRoot'])),
    step("什么时候真的写进存储(macOS,新进程读回):put 之后正常退出(没有 flush),新进程读到了 exit_noflush = yes;put 之后不 flush 立刻 kill -9,新进程仍然读到了 kill_noflush = yes;put + flush 后 kill -9,也读到了 kill_flushed = yes。这个后端(MacOSXPreferences)是同步写入的,不 flush 也不会丢——文档上 put 可能要等 flush 才持久,但不能把这个当作各平台通用的保证(Linux 的文件后端是异步的,我没有验证)。", t=tl(S(2)), done=lidx(S(2), 'put 之后正常退出', 'put(不 flush)后立刻 kill -9'), mark=lidx(S(2), 'put + flush 后 kill -9'), kv=KV([['put 后正常退出(不 flush)', '新进程读到'], ['put 后立刻 kill -9(不 flush)', '新进程仍然读到'], ['put + flush 后 kill -9', '新进程读到']], ['put 后立刻 kill -9(不 flush)'])),
    step("长度限制与类型:key 80 个字符成功、81 个字符抛 IllegalArgumentException(Key too long);value 8192 个字符成功、8193 个字符抛 IllegalArgumentException(Value too long);节点名 81 个字符抛 IllegalArgumentException(Node name … too long);key 为 null 抛 NullPointerException;value 含 NUL 字符抛 IllegalArgumentException。类型:putInt 存的字符串是 42,putBoolean 存 true,putByteArray 存 Base64(AQIDyA==),putDouble 存 3.5;getInt 读到的值是字符串 hello 时返回默认值 -1,getBoolean 读到 hello 返回默认值 true(解析不了不会抛异常);get(不存在, null) 返回 null;remove 之后 getInt 回到默认值。", t=tl(S(3)), done=lidx(S(3), 'key 80 个字符', 'key 81 个字符', 'value 8192 个字符', 'value 8193 个字符'), mark=lidx(S(3), '节点名 81 个字符', 'key 为 null', 'value 含 NUL', 'getInt(i) = 42', 'putInt(', 'remove 之后'), kv=KV([['长度上限', 'key 80、value 8192、节点名 80'], ['getInt / getBoolean 解析失败', '返回传入的默认值,不抛异常'], ['byte[]', '以 Base64 字符串存储']], ['getInt / getBoolean 解析失败'])),
    step("另一个进程改了值之后:本进程里 addPreferenceChangeListener 在本进程 put 时收到事件 watch=1(回调线程名是 Event Dispatch Thread,是 java.util.prefs 自己的线程);另一个进程写入 watch=2 并 flush 之后,本进程没有收到任何事件(包括 sync() 之后),但 get(\"watch\") 立刻就读到了 2。在这个后端上外部修改能被读到,监听器却不会通知——不能靠监听器实现“配置热更新”。", t=tl(S(4)), done=lidx(S(4), '本进程 put 之后收到的事件'), mark=lidx(S(4), '另一个进程', '等待另一个进程写入 watch=2', '调用 sync() 之后'), kv=KV([['本进程 put', '监听器收到 watch=1(线程 Event Dispatch Thread)'], ['另一个进程写入 watch=2', '本进程 get 立即读到 2,监听器没有事件']], ['另一个进程写入 watch=2'])),
    step("清理:对测试节点 removeNode() + flush() 之后 nodeExists = false,defaults read 里不再含有 j266test_zen。Preferences 不会自己过期,没有 removeNode 的节点会一直留在用户的偏好文件里。", t=tl(S(5)), done=lidx(S(5), 'removeNode + flush'), mark=lidx(S(5), '清理后 defaults read'), kv=KV([['removeNode + flush', 'nodeExists = false'], ['不清理', '节点一直留在 plist 里']], ['removeNode + flush'])),
]
A = mkartj('j266', 266, 'Java,java.util.prefs,Preferences,偏好设置,持久化,真实验证,动画演示',
    '在 macOS / JDK 21 上实测 java.util.prefs:userRoot 是 MacOSXPreferences,存在 com.apple.java.util.prefs.plist;put 不 flush 也立刻持久(kill -9 后仍读到);key 80 / value 8192 / 节点名 80 的上限;getInt 解析失败返回默认值;外部进程的修改能读到但监听器不通知;systemRoot 无权限写入。',
    'Preferences 是 JDK 自带的“轻量偏好设置”。这篇在 macOS 上用多个真实进程量出它存在哪里、什么时候真的持久、有哪些长度与类型的边界、监听器是否可靠,以及如何清理。',
    [('kill -9 后仍读到', '不 flush 就 kill -9:新进程读到了刚 put 的值(macOS 后端同步写入)'), ('80 / 8192', 'key(与节点名)与 value 的最大字符数,超过抛 IllegalArgumentException'), ('0 个事件', '另一个进程修改值之后,本进程监听器收到的事件数(但 get 立刻读到新值)')],
    [('实现与存储位置', None), ('什么时候持久', None), ('长度限制与类型', None), ('外部修改与监听器', None), ('清理', None)],
    steps, [ENV_J + '。JDK 21.0.12,macOS arm64(java.util.prefs 的后端是平台相关的:macOS 用 CFPreferences,Linux 用 ~/.java/.userPrefs 文件,Windows 用注册表);实验节点名是 /j266test_zen,实验结束后已删除', '没有验证:Linux 的文件后端(异步写入每 30 秒、系统级偏好需要 root)、Windows 注册表后端、systemRoot 在有权限时的行为、导出 / 导入 XML(exportNode / importPreferences)、多线程并发写入、偏好变化在 JVM 退出时的 flush 顺序'], 'java.util.prefs')
